parameters.jsCode:
// Prepare user payload with extracted skills and ranking metrics for Supabase
const cvResult = $input.first().json;

// Normalize candidate data
const skills = cvResult.skills || [];
const name = cvResult.name || cvResult.candidate_name || 'Freelancer';
const email = cvResult.email || cvResult.candidate_email || 'user@unstuck.app';
const title = cvResult.professional_title || 'Full-Stack Developer';
const exp = cvResult.experience_level || 'Mid-Level';
const summary = cvResult.summary || '';
const highMatchJobs = cvResult.high_score_jobs || [];
const metrics = cvResult.metrics || {};

return [{
  json: {
    user: {
      name: name,
      email: email,
      title: title,
      experience_level: exp,
      summary: summary,
      skills: skills,
      total_skills: skills.length,
      alertThreshold: 75,
      rank_score: metrics.total_score || (skills.length * 20),
      badge: metrics.badge || '🌱 Aspiring Talent',
      updatedAt: new Date().toISOString()
    },
    jobs: highMatchJobs,
    totalMatches: cvResult.matched_jobs_count || highMatchJobs.length,
    highScoreMatches: highMatchJobs.length,
    filename: cvResult.filename || 'cv.pdf'
  }
}];

// Prepare matched jobs data and rank info for notification & webhook response
const syncRes = $input.first().json;
const prevData = $('Format Profile for Supabase').first().json;

const user = prevData.user || {};
const rankInfo = syncRes.rank_info || {};
const jobs = prevData.jobs || [];

// Update user with live rank position
user.rank = rankInfo.rank || 1;
user.total_users = rankInfo.total_users || 50;
user.rank_score = rankInfo.total_score || user.rank_score;
user.badge = rankInfo.badge || user.badge;

return [{
  json: {
    user: user,
    jobs: jobs,
    threshold: user.alertThreshold || 75,
    highScoreMatches: jobs.length,
    totalMatches: prevData.totalMatches || jobs.length
  }
}];

// Format a high-conversion, bilingual responsive HTML email
const data = $input.first().json;
const user = data.user || {};
const jobs = data.jobs || [];
const userName = user.name || 'مبدع Unstuck';
const userEmail = user.email || '';
const threshold = data.threshold || 75;
const userRank = user.rank ? `#${user.rank}` : 'Top Pro';
const userBadge = user.badge || '⚡ Senior Pro';

const jobCards = jobs.slice(0, 8).map((job, i) => {
  const title = job.title || 'Untitled Opportunity';
  const platform = job.platform || 'منصة عمل حر';
  const score = job.match_score || job.score || 85;
  const matchedSkills = (job.matched_skills || []).slice(0, 5);
  const url = job.url || '#';
  const price = job.price || '$50 - $200';
  const duration = job.duration || 'أسبوع';
  const brief = (job.brief || '').substring(0, 160) + '...';

  const scoreColor = score >= 90 ? '#10b981' : score >= 80 ? '#3b82f6' : '#f59e0b';
  const scoreBg = score >= 90 ? '#ecfdf5' : score >= 80 ? '#eff6ff' : '#fef3c7';

  return `
    <div style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px; margin-bottom: 16px; box-shadow: 0 2px 8px rgba(0,0,0,0.04);">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px;">
        <div style="flex: 1;">
          <span style="display: inline-block; background: #f1f5f9; color: #475569; padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 700; margin-bottom: 6px;">📌 ${platform}</span>
          <h3 style="margin: 0 0 6px 0; font-size: 16px; color: #0f172a; line-height: 1.4;">${title}</h3>
        </div>
        <div style="background: ${scoreBg}; color: ${scoreColor}; border: 1px solid ${scoreColor}; padding: 6px 14px; border-radius: 999px; font-weight: 800; font-size: 15px; margin-left: 12px; white-space: nowrap;">
          ${score}% تطابق
        </div>
      </div>
      <p style="color: #64748b; font-size: 13.5px; line-height: 1.5; margin: 0 0 14px 0;">${brief}</p>
      <div style="display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 14px;">
        ${matchedSkills.map(s => `<span style="background: #fdf2f8; color: #be123c; border: 1px solid #fbcfe8; padding: 3px 10px; border-radius: 999px; font-size: 11.5px; font-weight: 600;">✓ ${s}</span>`).join(' ')}
      </div>
      <div style="display: flex; justify-content: space-between; align-items: center; border-top: 1px solid #f1f5f9; padding-top: 12px;">
        <div style="font-size: 13px; color: #334155;">💰 <strong>${price}</strong> &nbsp;•&nbsp; ⏱️ ${duration}</div>
        <a href="${url}" target="_blank" style="background: #be123c; color: #ffffff; text-decoration: none; padding: 8px 18px; border-radius: 8px; font-size: 13px; font-weight: 700; display: inline-block;">عرض المشروع والتقديم ←</a>
      </div>
    </div>`;
}).join('');

const html = `
<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head><meta charset="utf-8"></head>
<body style="margin: 0; padding: 0; background: #f8fafc; font-family: 'Segoe UI', Tahoma, Arial, sans-serif; direction: rtl;">
  <div style="max-width: 680px; margin: 24px auto; background: #ffffff; border-radius: 16px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 10px 30px rgba(0,0,0,0.06);">
    <!-- Header -->
    <div style="background: linear-gradient(135deg, #be123c 0%, #881337 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
      <div style="font-size: 32px; font-weight: 900; letter-spacing: -0.5px;">🚀 UNSTUCK</div>
      <div style="font-size: 14px; opacity: 0.9; margin-top: 6px;">رادار الوظائف الذكي والربط التلقائي عبر الـ CV</div>
    </div>
    <!-- Banner -->
    <div style="background: #fff1f2; border-bottom: 1px solid #ffe4e6; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center;">
      <div>
        <span style="font-size: 14px; color: #9f1239; font-weight: 700;">مرحباً يا ${userName}! 👋</span>
        <div style="font-size: 12px; color: #e11d48; margin-top: 2px;">تم استخراج مهاراتك من الـ CV وتحديث رادارك الشخصي بنجاح.</div>
      </div>
      <div style="text-align: left; background: #ffffff; padding: 6px 14px; border-radius: 8px; border: 1px solid #fecdd3;">
        <div style="font-size: 11px; color: #9f1239;">ترتيبك في المنصة</div>
        <div style="font-size: 15px; font-weight: 900; color: #be123c;">${userRank} <span style="font-size: 12px;">(${userBadge})</span></div>
      </div>
    </div>
    <!-- Content -->
    <div style="padding: 24px;">
      <h2 style="margin: 0 0 8px 0; font-size: 18px; color: #0f172a;">🎯 وجدنا لك ${jobs.length} وظيفة تتطابق بدقة مع مهاراتك!</h2>
      <p style="color: #64748b; font-size: 13.5px; margin: 0 0 20px 0;">المشاريع التالية تجاوزت حاجز التطابق المحدد لملفك (${threshold}%):</p>
      ${jobCards}
    </div>
    <!-- Footer -->
    <div style="background: #f8fafc; padding: 20px 24px; text-align: center; border-top: 1px solid #e2e8f0;">
      <p style="margin: 0; font-size: 12.5px; color: #64748b;">نظام Unstuck المستقل للأتمتة والربط الذكي بالمهام الحرة</p>
      <p style="margin: 6px 0 0 0; font-size: 11px; color: #94a3b8;">تصلك هذه الرسالة بناءً على إعدادات التنبيه التلقائي في ملفك الشخصي.</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    to: userEmail,
    subject: `🚀 Unstuck: جالك ${jobs.length} وظيفة متوافقة تماماً مع الـ CV والمهارات الخاصة بك!`,
    html: html,
    userName: userName,
    jobsCount: jobs.length,
    user: user,
    jobs: jobs
  }
}];

