parameters.jsCode:
// Fan out users from Supabase leaderboard response
const resp = $input.first().json;
const users = resp.leaderboard || [];
return users.map(u => ({ json: u }));

// Filter high score jobs for each user
const matchResponse = $input.first().json;
const jobs = matchResponse.jobs || matchResponse.matches || [];

let user;
try {
  user = $('Split Users Stream').first().json;
} catch (e) {
  user = { name: 'User', email: '', skills: [], total_score: 100, rank: 1 };
}

const threshold = 75;
const highScoreJobs = jobs.filter(job => {
  const score = job.match_score || job.score || 0;
  return score >= threshold;
});

return [{
  json: {
    user: user,
    threshold: threshold,
    totalMatches: jobs.length,
    highScoreMatches: highScoreJobs.length,
    jobs: highScoreJobs
  }
}];
